/**
 * Mirror of `fjall::Error`, flattened into FFI-friendly variants.
 */
public 
enum FfiError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    /**
     * I/O error
     */
    case Io(message: String
    )
    /**
     * Error inside the storage engine (lsm-tree)
     */
    case Storage(message: String
    )
    /**
     * Error during journal recovery
     */
    case JournalRecovery(message: String
    )
    /**
     * Database format version mismatch
     */
    case InvalidVersion(message: String
    )
    /**
     * Decompression failed
     */
    case Decompress(message: String
    )
    /**
     * A lock is poisoned (a thread panicked while holding it)
     */
    case Poisoned
    /**
     * The keyspace was deleted
     */
    case KeyspaceDeleted
    /**
     * The database is locked by another process
     */
    case Locked
    /**
     * The database is in an unrecoverable state
     */
    case Unrecoverable
    /**
     * The write batch was already committed and cannot be used again
     */
    case BatchConsumed
    /**
     * The transaction was already committed or rolled back
     */
    case TransactionConsumed
    /**
     * The transaction conflicted with another transaction and was not applied
     */
    case Conflict
    /**
     * Any other error
     */
    case Other(message: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

