    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Io(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Storage(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .JournalRecovery(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .InvalidVersion(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Decompress(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Poisoned
        case 7: return .KeyspaceDeleted
        case 8: return .Locked
        case 9: return .Unrecoverable
        case 10: return .BatchConsumed
        case 11: return .TransactionConsumed
        case 12: return .Conflict
        case 13: return .Other(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Io(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Storage(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .JournalRecovery(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidVersion(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Decompress(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case .Poisoned:
            writeInt(&buf, Int32(6))
        
        
        case .KeyspaceDeleted:
            writeInt(&buf, Int32(7))
        
        
        case .Locked:
            writeInt(&buf, Int32(8))
        
        
        case .Unrecoverable:
            writeInt(&buf, Int32(9))
        
        
        case .BatchConsumed:
            writeInt(&buf, Int32(10))
        
        
        case .TransactionConsumed:
            writeInt(&buf, Int32(11))
        
        
        case .Conflict:
            writeInt(&buf, Int32(12))
        
        
        case let .Other(message):
            writeInt(&buf, Int32(13))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


