@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiPersistMode: FfiConverterRustBuffer {
    typealias SwiftType = FfiPersistMode

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiPersistMode {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .buffer
        
        case 2: return .syncData
        
        case 3: return .syncAll
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiPersistMode, into buf: inout [UInt8]) {
        switch value {
        
        
        case .buffer:
            writeInt(&buf, Int32(1))
        
        
        case .syncData:
            writeInt(&buf, Int32(2))
        
        
        case .syncAll:
            writeInt(&buf, Int32(3))
        
        }
    }
}


